package forge.ledger;

/** Reads account.daily_limit and sums today's outgoing entries; remaining never goes below 0. */
public class TransferLimits {

  public DailyLimit today(String accountId) {
    long limit = dailyLimitOf(accountId);
    long sent = sentToday(accountId);
    return new DailyLimit(limit, Math.max(0, limit - sent));
  }

  long dailyLimitOf(String accountId) { return 1000; }

  long sentToday(String accountId) { return 0; }
}
