package forge.ledger;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class TransferLimitsTest {

  @Test
  void remainingIsTheLimitMinusTodaysTransfers() {
    TransferLimits limits = new TransferLimits() {
      @Override long sentToday(String accountId) { return 900; }
    };
    assertEquals(100, limits.today("acc-1").remaining());
  }

  @Test
  void remainingNeverGoesBelowZero() {
    TransferLimits limits = new TransferLimits() {
      @Override long sentToday(String accountId) { return 1200; }
    };
    assertEquals(0, limits.today("acc-1").remaining());
  }
}
